import 'package:flutter/material.dart';import '../widgets/ui.dart';import '../models/roles.dart';
class ModulesScreen extends StatelessWidget{const ModulesScreen({super.key,required this.roles,required this.open});final Set<AppRole> roles;final void Function(Feature) open;@override Widget build(BuildContext context){final a=allowedFeatures(roles);final entries=<({Feature f,String title,String subtitle,IconData icon})>[(f:Feature.content,title:'تأليف الدروس',subtitle:'التحرير والمراجعة والنشر',icon:Icons.edit_note),(f:Feature.library,title:'مكتبة الوسائط',subtitle:'المواد التعليمية والملفات',icon:Icons.perm_media_outlined),(f:Feature.finance,title:'الرسوم والمالية',subtitle:'الحسابات والرسوم',icon:Icons.account_balance_wallet_outlined),(f:Feature.staff,title:'شؤون الموظفين',subtitle:'إدارة الموظفين',icon:Icons.badge_outlined),(f:Feature.admissions,title:'الاستقبال والقبول',subtitle:'طلبات القبول',icon:Icons.support_agent_outlined),(f:Feature.users,title:'المستخدمون',subtitle:'إدارة الحسابات والصلاحيات',icon:Icons.manage_accounts_outlined),(f:Feature.classes,title:'الصفوف والشعب',subtitle:'دليل الصفوف',icon:Icons.class_outlined),(f:Feature.attendance,title:'الحضور',subtitle:'جلسات وسجلات الحضور',icon:Icons.fact_check_outlined),(f:Feature.courses,title:'المقررات والدروس',subtitle:'المقررات والمصادر',icon:Icons.menu_book_outlined)];return ListView(padding:const EdgeInsets.all(18),children:[const SaiHeader(title:'أنظمة الكلية',subtitle:'الخدمات المتاحة وفق صلاحيات حسابك'),...entries.where((e)=>a.contains(e.f)).map((e)=>SaiTile(title:e.title,subtitle:e.subtitle,icon:e.icon,onTap:()=>open(e.f)))]);}}
